from pathlib import Path
import base64,gzip,json
out=Path(__file__).resolve().parent
payload=base64.b64encode(gzip.compress((out/'data.json').read_bytes(),compresslevel=9)).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>电路优化轨迹观察器</title>
<style>body{margin:0;background:#f5f7fc;color:#18243a;font:15px -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1500px;margin:auto;padding:30px}h1{font-size:29px;margin:0 0 12px}h2{font-size:18px}.muted{color:#64748b;line-height:1.7}.card{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:20px;margin:18px 0}.row{display:flex;gap:18px;flex-wrap:wrap;align-items:center}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.stat{flex:1;min-width:140px;padding:14px;background:#f1f5fb;border-radius:10px}.stat strong{display:block;font-size:27px;margin-top:5px}select,button{border:1px solid #cbd5e1;border-radius:8px;background:white;padding:9px 12px;font:inherit;color:inherit}button{cursor:pointer}button:hover{background:#eef2ff}input[type=range]{flex:1;min-width:200px}.plot{width:100%;height:270px}.circuit{overflow:auto;max-height:630px;border:1px solid #e2e8f0;border-radius:10px}.legend{font-size:13px;color:#64748b}.badge{display:inline-block;padding:4px 10px;border-radius:8px;background:#e0e7ff;color:#3730a3}a{color:#2563eb}details{line-height:1.7}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:7px;border-bottom:1px solid #e2e8f0}.tip{color:#92400e;background:#fffbeb;padding:15px;border-radius:10px}@media(max-width:850px){.grid{grid-template-columns:1fr}main{padding:15px}}</style>
<main><h1>电路优化轨迹观察器</h1><p class="muted">逐步查看门数变化、暂时扩张与局部电路重写。数据来自 Downloads 中两组已保存的成功轨迹。</p>
<div class="tip">每个目录是一段优化过程，起点并不相同。横轴是变换步数，不是耗时。文件没有失败尝试或策略概率，不能凭这些轨迹判断强化学习是否优于随机策略。</div>
<div class="card row"><label>电路 <select id="dataset"></select></label><label>轨迹段 <select id="path"></select></label><button id="best">最短的最佳终点段</button><a href="overview.png" target="_blank">总览图片</a><a href="overview.pdf" target="_blank">PDF</a><a href="loops.png" target="_blank">结构去环图</a><a href="transitions.csv">原始统计 CSV</a></div>
<div id="stats" class="row"></div><div class="grid"><div class="card"><h2>当前轨迹：门数与历史最优</h2><svg id="curve" class="plot" viewBox="0 0 700 270"></svg><p class="legend">蓝：当前门数 · 绿虚线：当前段历史最优 · 橙：选中的状态；点击曲线跳转。</p></div><div class="card"><h2>全部轨迹：长度与终点</h2><svg id="scatter" class="plot" viewBox="0 0 700 270"></svg><p class="legend">每个圆是一段成功轨迹，点击可切换；横轴为段内变换次数。</p></div></div>
<div class="card"><div class="row"><button id="prev">上一步</button><button id="play">播放</button><button id="next">下一步</button><input id="step" type="range" min="0" value="0"><span id="position"></span></div><p id="action" class="muted"></p><div class="row"><label>绘图缩放 <input id="zoom" type="range" min="55" max="160" value="85"></label><button id="export">保存当前电路 SVG</button><label><input id="dim" type="checkbox" checked> 淡化未改变的门</label></div><p class="legend">蓝色为 CNOT，紫色为 Rz，灰色为 H/X。红/绿标出相邻 QASM 序列中删除/新增的门；可交换门的排列变化也会被标出，因此颜色不是规则匹配子图的精确边界。</p><div class="grid"><div><h2 id="beforetitle"></h2><div id="before" class="circuit"></div></div><div><h2 id="aftertitle"></h2><div id="after" class="circuit"></div></div></div></div>
<div class="grid"><div class="card"><h2>当前段的步数构成</h2><svg id="bars" class="plot" viewBox="0 0 700 270"></svg><p id="pathnote" class="muted"></p></div><div class="card"><h2>当前段常用变换</h2><div id="rules"></div><p class="muted">xfer ID 是规则索引；没有生成轨迹时的 ECC 文件，不能给它可靠的规则名称。贡献是每次应用后的即时门数变化，不等于长期价值。</p></div></div>
<div class="card"><details><summary>数据解释与验证范围</summary><p>文件名为 step_gatecount_reward_node_xfer.qasm。已核对所有相邻状态：文件 i 的 reward/node/xfer 对应 i → i+1 的动作；最后一个文件是终态占位，统计规则时排除。门数、门类型计数与深度来自实际 QASM 解析。深度采用无硬件连通性限制的 ASAP 并行层数。</p><p>所有 Barenco 的不同结构状态进行了完整 32×32 酉矩阵对比，允许全局相位。GF 代表段只对起点、最大门数状态、终点做一个随机复数状态向量检查；它是概率性检查，不能代替全部状态的形式验证。详细误差见 <a href="summary.json">summary.json</a>。</p><p>结构重复指在相同量子位上，忽略互不依赖门的排序及 Rz 的 2π 全局相位后 DAG 指纹相同；不代表所有功能等价电路都已识别。</p></details></div></main>
<script>
const payload='__PAYLOAD__';let DATA,D,P,index=0,timer=null;const $=id=>document.getElementById(id),esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function frame(svg,xlabel,ylabel){svg.innerHTML='<path d="M55 20V225H675" fill="none" stroke="#94a3b8"/><text x="350" y="263" text-anchor="middle" fill="#64748b">'+xlabel+'</text><text x="15" y="15" fill="#64748b">'+ylabel+'</text>'}
function text(x,y,s,color='#64748b'){return `<text x="${x}" y="${y}" fill="${color}" font-size="12">${esc(s)}</text>`}
function selectPath(id){P=D.paths.find(p=>p.summary.id===id);$('path').value=id;index=0;$('step').max=P.states.length-1;render()}
function selectDataset(){D=DATA[+$('dataset').value];$('path').innerHTML=D.paths.map(p=>`<option value="${p.summary.id}">${p.summary.id}：${p.summary.start} → ${p.summary.end}，${p.summary.steps} 步</option>`).join('');selectPath(D.representative)}
function render(){let s=P.summary,t=D.totals;$('stats').innerHTML=[['当前段起点 → 终点',`${s.start} → ${s.end}`],['变换次数',s.steps],['最大暂时扩张',`+${s.barrier} 门`],['当前段结构重访',s.revisited],['该电路全部成功段',D.paths.length]].map(([k,v])=>`<div class="stat">${k}<strong>${v}</strong></div>`).join('');plotCurve();scatter();bars();rules();drawStep()}
function plotCurve(){let svg=$('curve'),v=P.states.map(r=>r.gates),lo=Math.min(...v)-1,hi=Math.max(...v)+1;frame(svg,'变换步数','门数');let x=i=>55+620*i/Math.max(1,v.length-1),y=g=>225-200*(g-lo)/(hi-lo);for(let g=lo;g<=hi;g++){svg.innerHTML+=`<path d="M55 ${y(g)}H675" stroke="#eef2f7"/>`+text(20,y(g)+4,g)}let best=v[0],points=v.map((g,i)=>`${x(i)},${y(g)}`).join(' '),minpoints=v.map((g,i)=>{best=Math.min(best,g);return `${x(i)},${y(best)}`}).join(' ');svg.innerHTML+=`<polyline points="${points}" fill="none" stroke="#2563eb" stroke-width="2"/><polyline points="${minpoints}" fill="none" stroke="#059669" stroke-width="2" stroke-dasharray="6 4"/><circle id="cursor" cx="${x(index)}" cy="${y(v[index])}" r="5" fill="#f97316"/>`+text(55,245,0)+text(645,245,v.length-1);svg.onclick=e=>{let r=svg.getBoundingClientRect();index=Math.max(0,Math.min(v.length-1,Math.round(((e.clientX-r.left)*700/r.width-55)/620*(v.length-1))));drawStep();plotCurve()}}
function scatter(){let svg=$('scatter'),ss=D.paths.map(p=>p.summary),max=Math.max(...ss.map(s=>s.steps)),lo=Math.min(...ss.map(s=>s.end))-1,hi=Math.max(...ss.map(s=>s.end))+1;frame(svg,'段内变换次数','终点门数');for(let k=0;k<=4;k++)svg.innerHTML+=text(48+620*k/4,245,Math.round(max*k/4));for(let k=0;k<=4;k++)svg.innerHTML+=text(15,228-200*k/4,Math.round(lo+(hi-lo)*k/4));for(let s of ss){svg.innerHTML+=`<circle data-path="${s.id}" cx="${55+620*s.steps/max}" cy="${225-200*(s.end-lo)/(hi-lo)}" r="${s.id===P.summary.id?7:4}" fill="${s.id===P.summary.id?'#f97316':'#7c3aed'}" opacity=".7" style="cursor:pointer"><title>${s.id}：${s.start}→${s.end}，${s.steps} 步，扩张 +${s.barrier}</title></circle>`}svg.querySelectorAll('circle').forEach(e=>e.onclick=()=>selectPath(e.dataset.path))}
function bars(){let s=P.summary,svg=$('bars'),v=[s.down,s.neutral,s.up],colors=['#059669','#64748b','#ef4444'],names=['门数减少','门数不变','门数增加'],max=Math.max(...v,1);frame(svg,'变换类别','次数');v.forEach((a,i)=>{let h=170*a/max,x=105+i*185;svg.innerHTML+=`<rect x="${x}" y="${225-h}" width="100" height="${h}" rx="5" fill="${colors[i]}"/>`+text(x+15,210-h,`${a} (${(100*a/Math.max(1,s.steps)).toFixed(1)}%)`)+text(x+15,245,names[i])});$('pathnote').textContent=`净减少 ${s.gain} 门；最高 ${s.peak} 门；首次低于起点在第 ${s.first_improvement??'—'} 步。相同结构再次出现 ${s.revisited} 次。按 DAG 指纹去环示意可缩至 ${s.loop_erased_steps} 步（尚未重放规则）。`}
function rules(){let entries=Object.entries(P.summary.ruledata).sort((a,b)=>b[1].uses-a[1].uses).slice(0,12);$('rules').innerHTML='<table><tr><th>ID</th><th>次数</th><th>净减少门数</th><th>减少 / 不变 / 增加</th></tr>'+entries.map(([id,v])=>`<tr><td>${id}</td><td>${v.uses}</td><td>${v.net_gate_reduction}</td><td>${v.down} / ${v.neutral} / ${v.up}</td></tr>`).join('')+'</table>'}
function opkey(o){return `${o.g}(${o.p}) ${o.q.join(',')}`}
function changes(a,b){let n=a.length,m=b.length,dp=Array.from({length:n+1},()=>new Uint16Array(m+1)),aa=a.map(opkey),bb=b.map(opkey);for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=aa[i]===bb[j]?1+dp[i+1][j+1]:Math.max(dp[i+1][j],dp[i][j+1]);let ca=new Set(a.map((_,i)=>i)),cb=new Set(b.map((_,i)=>i)),i=0,j=0;while(i<n&&j<m){if(aa[i]===bb[j]){ca.delete(i++);cb.delete(j++)}else if(dp[i+1][j]>=dp[i][j+1])i++;else j++}return [ca,cb]}
function circuit(state,changed,type){let z=+$('zoom').value/100,dx=58*z,dy=37*z,maxcol=Math.max(...state.ops.map(o=>o.col)),width=Math.max(600,95+dx*(maxcol+1)),height=60+dy*state.n,out=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" style="background:white" font-family="sans-serif">`;for(let q=0;q<state.n;q++)out+=`<line x1="65" x2="${width-20}" y1="${35+q*dy}" y2="${35+q*dy}" stroke="#cbd5e1"/>`+text(8,39+q*dy,`q[${q}]`);state.ops.forEach((o,i)=>{let x=65+o.col*dx,ys=o.q.map(q=>35+q*dy),ischange=changed.has(i),stroke=ischange?(type==='before'?'#dc2626':'#059669'):(o.g==='cx'?'#2563eb':o.g==='rz'?'#7c3aed':'#475569'),opacity=!ischange&&$('dim').checked?.35:1;out+=`<g opacity="${opacity}"><title>QASM gate ${i}: ${esc(opkey(o))}</title>`;if(o.g==='cx'){out+=`<line x1="${x}" x2="${x}" y1="${ys[0]}" y2="${ys[1]}" stroke="${stroke}" stroke-width="2"/><circle cx="${x}" cy="${ys[0]}" r="4" fill="${stroke}"/><circle cx="${x}" cy="${ys[1]}" r="9" fill="white" stroke="${stroke}" stroke-width="2"/><path d="M${x-6} ${ys[1]}h12M${x} ${ys[1]-6}v12" stroke="${stroke}"/>`}else{let label=o.g.toUpperCase();if(o.g==='rz')label=(o.p.replace('pi*','')+'π').replace('1.750000π','−π/4').replace('0.250000π','π/4');out+=`<rect x="${x-22*z}" y="${ys[0]-12*z}" width="${44*z}" height="${24*z}" rx="4" fill="white" stroke="${stroke}" stroke-width="${ischange?2:1}"/><text x="${x}" y="${ys[0]+4*z}" text-anchor="middle" fill="${stroke}" font-size="${10*z}">${esc(label)}</text>`}out+='</g>'});return out+'</svg>'}
function drawStep(){let a=P.states[index],b=P.states[Math.min(index+1,P.states.length-1)],last=index===P.states.length-1,[ca,cb]=last?[new Set(),new Set()]:changes(a.ops,b.ops);$('step').value=index;$('position').textContent=`${index} / ${P.states.length-1}`;$('action').innerHTML=last?`<span class="badge">终态</span> ${a.gates} 门；没有下一动作。`:`<span class="badge">${a.gates} → ${b.gates} 门</span>　即时奖励 ${a.reward}　变换 ID ${a.xfer}　节点 ID ${a.node}　H/CX/Rz：${a.counts.h||0}/${a.counts.cx||0}/${a.counts.rz||0}　深度 ${a.depth} → ${b.depth}`;$('beforetitle').textContent=`状态 ${index}：${a.gates} 门`;$('aftertitle').textContent=last?'终态（同左）':`状态 ${index+1}：${b.gates} 门`;$('before').innerHTML=circuit(a,ca,'before');$('after').innerHTML=circuit(b,cb,'after')}
$('dataset').onchange=selectDataset;$('path').onchange=()=>selectPath($('path').value);$('best').onclick=()=>selectPath(D.representative);$('step').oninput=()=>{index=+$('step').value;drawStep();plotCurve()};$('prev').onclick=()=>{index=Math.max(0,index-1);drawStep();plotCurve()};$('next').onclick=()=>{index=Math.min(P.states.length-1,index+1);drawStep();plotCurve()};$('zoom').oninput=drawStep;$('dim').onchange=drawStep;$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='播放'}else{$('play').textContent='暂停';timer=setInterval(()=>{if(index>=P.states.length-1){$('play').click();return}index++;drawStep();plotCurve()},550)}};$('export').onclick=()=>{let s=$('before').innerHTML,b=new Blob([s],{type:'image/svg+xml'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`${D.name}_${P.summary.id}_step${index}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};document.onkeydown=e=>{if(e.target.tagName==='SELECT')return;if(e.key==='ArrowRight')$('next').click();if(e.key==='ArrowLeft')$('prev').click()};
(async()=>{try{const bytes=Uint8Array.from(atob(payload),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));DATA=JSON.parse(await new Response(stream).text());$('dataset').innerHTML=DATA.map((d,i)=>`<option value="${i}">${d.name}</option>`).join('');selectDataset()}catch(e){document.querySelector('main').insertAdjacentHTML('afterbegin',`<p class="tip">加载失败：${esc(e.message)}。请使用新版 Chrome 或 Safari 打开此页面。</p>`)}})();
</script></html>'''
(out/'trajectory_viewer.html').write_text(html.replace('__PAYLOAD__',payload))
print('viewer bytes', (out/'trajectory_viewer.html').stat().st_size)
